def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Aggregate statistics from the full match.
    cc = cd = dc = dd = 0
    my_d = opp_d = 0
    for a, b in history:
        if a == 'C':
            if b == 'C':
                cc += 1
            else:
                cd += 1
        else:
            my_d += 1
            if b == 'C':
                dc += 1
            else:
                dd += 1
        if b == 'D':
            opp_d += 1

    remaining = 100 - n

    # Recent windows for responsiveness.
    r = history[-6:] if n >= 6 else history
    r_op_d = sum(1 for a, b in r if b == 'D')
    r_my_d = sum(1 for a, b in r if a == 'D')
    r_len = len(r)

    last_my, last_op = history[-1]

    # Endgame: squeeze maximum points.
    if remaining <= 1:
        return 'D'

    if remaining <= 4:
        # Defect unless the opponent has been essentially a pure cooperator.
        if opp_d == 0:
            return 'C'
        return 'D'

    if remaining <= 10:
        if opp_d * 6 <= n:
            return 'C'
        return 'D'

    # Almost pure cooperator: exploit heavily but keep them cooperating.
    if n >= 12 and opp_d == 0:
        if remaining <= 25:
            return 'D'
        return 'D' if (n % 3) != 0 else 'C'

    # Nearly pure cooperator.
    if n >= 12 and opp_d * 12 <= n:
        if remaining <= 30:
            return 'D'
        if last_op == 'C':
            return 'D' if (n % 4) != 0 else 'C'
        return 'C'

    # Heavily defective opponent: defect back, rare probe.
    if opp_d * 2 >= n:
        if last_op == 'C' and r_op_d < r_len:
            # Reward a rare cooperative move sometimes to keep them probing.
            if (n % 5) == 0:
                return 'C'
            return 'D'
        if r_op_d * 3 >= r_len * 2:
            return 'D'
        return 'D' if (n % 7) != 0 else 'C'

    # Moderate defector: punish, but forgive to escape mutual defection.
    if opp_d * 3 >= n:
        if r_op_d * 2 >= r_len:
            # If we've been locked in DD, occasionally try C.
            if last_my == 'D' and last_op == 'D' and r_my_d * 2 >= r_len:
                if rng.random() < 0.2:
                    return 'C'
            return 'D'
        if last_op == 'D':
            return 'D'
        # Opponent cooperated recently: reciprocate unless we're behind.
        if dc >= cd + 2 and (n % 3) == 0:
            return 'D'
        return 'C'

    # Mostly cooperative: cooperate, but retaliate on recent defection.
    if last_op == 'D':
        if last_my == 'D':
            # mutual defection — try to restore cooperation.
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        # We cooperated, they defected: punish firmly but briefly.
        return 'D'

    # Last opponent move was C; consider exploiting with a calibrated rate.
    if r_op_d == 0 and r_len >= 4:
        if opp_d * 10 <= n and (n % 5) == 0 and remaining > 15:
            return 'D'
        return 'C'

    # Slightly mixed opponent, last move C but some recent defections.
    if r_my_d * 2 >= r_len:
        # We've been defecting a lot; try to return to C.
        return 'C'

    if cc >= cd + dc:
        return 'C'
    if rng.random() < 0.2:
        return 'D'
    return 'C'
